namespace Mythosia.Test.Integrity;

internal static class Crc8AutosarH2FPublishedVectors
{
    // Thirty distinct nonempty inputs with answers frozen in primary sources.
    // Expected values below are published facts, not values generated by this
    // library, a lookup table, or an external calculator at test execution time.
    // CRC-8/AUTOSAR (H2F): poly=0x2F, init=0xFF, refin/refout=false, xorout=0xFF.
    //
    // AUTOSAR CP R24-11, page 21, [SWS_Crc_00075] and [SWS_Crc_00076].
    // https://www.autosar.org/fileadmin/standards/R24-11/CP/AUTOSAR_CP_SWS_CRCLibrary.pdf
    // Retrieved 2026-10-15; PDF SHA-256:
    // 496f7e2885c308f382aa2b9f9bf3f7b472546731fcde384fae622ace3cc1b92f
    // The seven table rows and the standard check are numeric facts only;
    // specification prose and its layout are not reproduced.
    //
    // autosar-e2e fixed CRC tests independently publish the same seven rows:
    // https://github.com/zariiii9003/autosar-e2e/blob/263c08172acfcb87cd3f9ad37dbdbddd8f5da075/test/test_crc.py#L38-L67
    // Its nineteen distinct Profile 2 fixtures publish complete output frames:
    // https://github.com/zariiii9003/autosar-e2e/blob/263c08172acfcb87cd3f9ad37dbdbddd8f5da075/test/test_p02.py#L5-L66
    // Profile 2 hashes frame[1..length] followed by data_id_list[counter], and
    // stores the resulting CRC in frame[0]. This ordering is explicit here:
    // https://github.com/zariiii9003/autosar-e2e/blob/263c08172acfcb87cd3f9ad37dbdbddd8f5da075/src/e2e/p02.c#L78-L90
    // Each imported answer is the literal published frame[0], not a CRC value
    // inferred from residue arithmetic. Duplicate length/type/split tests and
    // deliberately corrupt frames are omitted. The raw CRC library does not
    // implement the AUTOSAR E2E Profile 2 framing protocol.
    //
    // Two further literal hex/answer pairs are from js-crc's AUTOSAR tests:
    // https://github.com/taichunmin/js-crc/blob/609858d9743ea2884715c810932c0aa3daf084bc/lib/crc8.test.ts#L48-L56
    // CRC-Forge publishes an all-byte-values binary fixture (H2F is index 1):
    // https://github.com/CodeName-666/CRC-Forge/blob/b54bea45bb929da4379a6f0bbd2b8e5a4ec4a277/test/test_crc/test_main.cpp#L72-L85
    //
    // The imported project fixtures are MIT licensed. Their notices follow;
    // the common permission and disclaimer text applies to all three sources.
    /*
     * MIT License
     *
     * Copyright (c) 2022-present Artur Drogunow <artur.drogunow@zf.com>
     * Copyright (c) 2024 戴均民
     * Copyright (c) 2026 Christof Seidel
     *
     * Permission is hereby granted, free of charge, to any person obtaining a copy
     * of this software and associated documentation files (the "Software"), to deal
     * in the Software without restriction, including without limitation the rights
     * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
     * copies of the Software, and to permit persons to whom the Software is
     * furnished to do so, subject to the following conditions:
     *
     * The above copyright notice and this permission notice shall be included in all
     * copies or substantial portions of the Software.
     *
     * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
     * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
     * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
     * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
     * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
     * OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
     * SOFTWARE.
     */
    internal static IEnumerable<object[]> Cases()
    {
        yield return new object[] { "AUTOSAR R24-11 table 1", Convert.FromHexString("00000000"), (byte)0x12 };
        yield return new object[] { "AUTOSAR R24-11 table 2", Convert.FromHexString("F20183"), (byte)0xC2 };
        yield return new object[] { "AUTOSAR R24-11 table 3", Convert.FromHexString("0FAA0055"), (byte)0xC6 };
        yield return new object[] { "AUTOSAR R24-11 table 4", Convert.FromHexString("00FF5511"), (byte)0x77 };
        yield return new object[] { "AUTOSAR R24-11 table 5", Convert.FromHexString("332255AABBCCDDEEFF"), (byte)0x11 };
        yield return new object[] { "AUTOSAR R24-11 table 6", Convert.FromHexString("926B55"), (byte)0x33 };
        yield return new object[] { "AUTOSAR R24-11 table 7", Convert.FromHexString("FFFFFFFF"), (byte)0x6C };
        yield return new object[] { "AUTOSAR standard check 123456789", Convert.FromHexString("313233343536373839"), (byte)0xDF };

        // test_e2e_p02_protect: data_id_list is 00..00, then 00..0F.
        yield return new object[] { "autosar-e2e P02 zero data", Convert.FromHexString("0100000000000000"), (byte)0x45 };
        yield return new object[] { "autosar-e2e P02 range data counter 2", Convert.FromHexString("0202030405060702"), (byte)0xBC };
        yield return new object[] { "autosar-e2e P02 range data counter 1", Convert.FromHexString("0102030405060701"), (byte)0x61 };

        // test_e2e_p02_protect_increment: data_id_list is 01..10.
        // Seven published payload bytes plus the selected one-byte Data ID.
        yield return new object[] { "autosar-e2e P02 increment counter 01", Convert.FromHexString("0100000000000002"), (byte)0x1B };
        yield return new object[] { "autosar-e2e P02 increment counter 02", Convert.FromHexString("0200000000000003"), (byte)0x98 };
        yield return new object[] { "autosar-e2e P02 increment counter 03", Convert.FromHexString("0300000000000004"), (byte)0x31 };
        yield return new object[] { "autosar-e2e P02 increment counter 04", Convert.FromHexString("0400000000000005"), (byte)0x0D };
        yield return new object[] { "autosar-e2e P02 increment counter 05", Convert.FromHexString("0500000000000006"), (byte)0x18 };
        yield return new object[] { "autosar-e2e P02 increment counter 06", Convert.FromHexString("0600000000000007"), (byte)0x9B };
        yield return new object[] { "autosar-e2e P02 increment counter 07", Convert.FromHexString("0700000000000008"), (byte)0x65 };
        yield return new object[] { "autosar-e2e P02 increment counter 08", Convert.FromHexString("0800000000000009"), (byte)0x08 };
        yield return new object[] { "autosar-e2e P02 increment counter 09", Convert.FromHexString("090000000000000A"), (byte)0x1D };
        yield return new object[] { "autosar-e2e P02 increment counter 10", Convert.FromHexString("0A0000000000000B"), (byte)0x9E };
        yield return new object[] { "autosar-e2e P02 increment counter 11", Convert.FromHexString("0B0000000000000C"), (byte)0x37 };
        yield return new object[] { "autosar-e2e P02 increment counter 12", Convert.FromHexString("0C0000000000000D"), (byte)0x0B };
        yield return new object[] { "autosar-e2e P02 increment counter 13", Convert.FromHexString("0D0000000000000E"), (byte)0x1E };
        yield return new object[] { "autosar-e2e P02 increment counter 14", Convert.FromHexString("0E0000000000000F"), (byte)0x9D };
        yield return new object[] { "autosar-e2e P02 increment counter 15", Convert.FromHexString("0F00000000000010"), (byte)0xCD };
        yield return new object[] { "autosar-e2e P02 increment counter 00", Convert.FromHexString("0000000000000001"), (byte)0x0E };

        yield return new object[] { "js-crc single ASCII 1", Convert.FromHexString("31"), (byte)0x4F };
        yield return new object[] { "js-crc Hello World!", Convert.FromHexString("48656C6C6F20576F726C6421"), (byte)0x37 };
        yield return new object[] { "CRC-Forge all byte values", Enumerable.Range(0, 256).Select(value => (byte)value).ToArray(), (byte)0x06 };
    }
}
